installer-gui-script.script:

var MACFUSE = '/Library/Filesystems/macfuse.fs';
var MACFUSE_MIN = '5.5.0'; // NTFSMAC_MACFUSE_MIN_* of src/daemon/internal.h
function refuse(title, message) {
    my.result.type = 'Fatal';
    my.result.title = title;
    my.result.message = message;
    return false;
}
function ntfsmacCheck() {
    if (!system.files.fileExistsAtPath(MACFUSE)) {
        return refuse('macFUSE is required',
            'Install macFUSE ' + MACFUSE_MIN + ' or newer and turn its file system extension on in System Settings, then run this installer again. ntfs-macos does not include macFUSE.');
    }
    var b = system.files.bundleAtPath(MACFUSE);
    var v = b ? (b.CFBundleShortVersionString || b.CFBundleVersion) : null;
    if (!v || system.compareVersions(v, MACFUSE_MIN) < 0) {
        return refuse('macFUSE is too old',
            'ntfs-macos needs macFUSE ' + MACFUSE_MIN + ' or newer; this Mac has ' + (v || 'an unknown version') + '. Update macFUSE, then run this installer again.');
    }
    var others = [['/Library/Filesystems/ufsd_NTFS.fs', 'Paragon NTFS'],
                  ['/Library/Filesystems/tuxera_ntfs.fs', 'Tuxera NTFS']];
    for (var i = 0; i < others.length; i++) {
        if (system.files.fileExistsAtPath(others[i][0])) {
            return refuse('Another NTFS driver is installed',
                others[i][1] + ' (' + others[i][0] + ') is installed. ntfs-macos does not install next to another NTFS driver, because two drivers could write to one volume. Remove it with its own uninstaller first.');
        }
    }
    return true;
}
